import bcrypt

# bcrypt는 자동으로 salt를 생성하고 반복 해싱을 수행하여 무차별 대입 공격에 강합니다.
def hash_password(password: str) -> str:
    # bcrypt를 사용하여 salt 포함 해시 생성 (MD5 대비 연산 비용이 높아 brute-force 방어)
    return bcrypt.hashpw(password.encode("utf-8"), bcrypt.gensalt()).decode("utf-8")

def verify_password(password: str, stored_hash: str) -> bool:
    # bcrypt의 상수 시간 비교로 타이밍 공격도 방어
    return bcrypt.checkpw(password.encode("utf-8"), stored_hash.encode("utf-8"))
```

한줄 요약: MD5는 salt 없이 빠른 해시를 생성해 무차별 대입·레인보우 테이블 공격에 취약하므로, 자동 salt 생성과 비용 인수(cost factor)를 지원하는 `bcrypt`로 교체하여 패스워드 해싱 보안을 강화했습니다.
